<?php
 namespace QQWorld\Framework\View\Element\Message; class MessageConfigurationsPool { private $configurationsMap; public function __construct( array $configurationsMap = [] ) { array_walk( $configurationsMap, function (array &$configuration) { if (!isset($configuration['renderer']) || !is_string($configuration['renderer']) ) { throw new \InvalidArgumentException('Renderer should be defined.'); } if (isset($configuration['data']) && !is_array($configuration['data']) ) { throw new \InvalidArgumentException('Data should be of array type.'); } if (!isset($configuration['data'])) { $configuration['data'] = []; } } ); $this->configurationsMap = $configurationsMap; } public function getMessageConfiguration($identifier) { return !isset($this->configurationsMap[$identifier]) ? null : $this->configurationsMap[$identifier]; } } 